// 0/1 KNAPSACK — 2D DP: O(n*W) time and space
function knapsack01_2D(weights, values, capacity) {
    const n = weights.length;
    // dp[i][w] = max value using first i items with capacity w
    const dp = Array.from({length: n+1}, () => new Array(capacity+1).fill(0));

    for (let i = 1; i <= n; i++) {
        const wt  = weights[i-1];
        const val = values[i-1];
        for (let w = 0; w <= capacity; w++) {
            dp[i][w] = dp[i-1][w]; // exclude item i
            if (wt <= w) {
                dp[i][w] = Math.max(dp[i][w], dp[i-1][w-wt] + val); // include
            }
        }
    }
    return dp[n][capacity];
}

// 0/1 KNAPSACK — 1D space-optimised: O(n*W) time, O(W) space
function knapsack01_1D(weights, values, capacity) {
    const dp = new Array(capacity+1).fill(0);

    for (let i = 0; i < weights.length; i++) {
        const wt  = weights[i];
        const val = values[i];
        // CRITICAL: iterate RIGHT TO LEFT
        // This ensures dp[w-wt] is from BEFORE item i was considered
        for (let w = capacity; w >= wt; w--) {
            dp[w] = Math.max(dp[w], dp[w-wt] + val);
        }
        // If we iterated LEFT TO RIGHT:
        // dp[wt]  updated first -> includes item i once
        // dp[2wt] updated next  -> sees dp[wt] already updated -> includes item i TWICE
        // That would be unbounded knapsack, not 0/1
    }
    return dp[capacity];
}

// TEST
const weights  = [2, 3, 4, 5];
const values   = [3, 4, 5, 6];
const capacity = 8;
console.log(knapsack01_2D(weights, values, capacity)); // 10 (items 1,3: wt=2+4, val=3+5=8? or items 0,1: wt=5, val=7?)
// Trace: item0(wt=2,val=3),item1(wt=3,val=4),item2(wt=4,val=5),item3(wt=5,val=6)
// Best: item0+item2(wt=2+4=6,val=3+5=8) or item1+item2(wt=7,val=9) or item0+item3(wt=7,val=9)
// or item2+item3(wt=9>8 no). Answer=10: item1+item3(wt=3+5=8,val=4+6=10)
console.log(knapsack01_1D(weights, values, capacity)); // 10

// UNBOUNDED KNAPSACK (for contrast) — LEFT TO RIGHT
function knapsackUnbounded(weights, values, capacity) {
    const dp = new Array(capacity+1).fill(0);
    for (let i = 0; i < weights.length; i++) {
        for (let w = weights[i]; w <= capacity; w++) { // LEFT TO RIGHT
            dp[w] = Math.max(dp[w], dp[w-weights[i]] + values[i]);
        }
    }
    return dp[capacity];
}

