// TARGET SUM (#494) — O(n * sum) time, O(sum) space
function findTargetSumWays(nums, target) {
    const sum = nums.reduce((a, b) => a + b, 0);

    // Validity check:
    // We need P = (sum + target) / 2 to be a non-negative integer
    if ((sum + target) % 2 !== 0) return 0;  // (sum+target) must be even
    if (Math.abs(target) > sum) return 0;     // target unreachable

    const subsetTarget = (sum + target) / 2; // P: subset sum to reach

    // Count subsets summing to subsetTarget (0/1 knapsack count variant)
    const dp = new Array(subsetTarget + 1).fill(0);
    dp[0] = 1; // one way to make sum 0: empty subset

    for (const num of nums) {
        // RIGHT TO LEFT: each num used at most once
        for (let j = subsetTarget; j >= num; j--) {
            dp[j] += dp[j - num];
        }
    }
    return dp[subsetTarget];
}

// TRACE on nums=[1,1,1,1,1], target=3:
// sum=5, P=(5+3)/2=4
// Find: how many subsets of [1,1,1,1,1] sum to 4?
// Answer: C(5,4) = 5 (choose any 4 of the 5 ones)
console.log(findTargetSumWays([1,1,1,1,1], 3)); // 5
console.log(findTargetSumWays([1], 1));          // 1
console.log(findTargetSumWays([1], 2));          // 0 (unreachable)

// NAIVE DFS for comparison (O(2^n))
function findTargetSumWays_dfs(nums, target) {
    let count = 0;
    function dfs(i, current) {
        if (i === nums.length) {
            if (current === target) count++;
            return;
        }
        dfs(i+1, current + nums[i]); // assign +
        dfs(i+1, current - nums[i]); // assign -
    }
    dfs(0, 0);
    return count;
}
// Correct but O(2^n): for n=20, 2^20 = 1M calls; for n=30, over 1B

