// PARTITION EQUAL SUBSET SUM (#416) — O(n * sum/2) time, O(sum/2) space
function canPartition(nums) {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % 2 !== 0) return false; // odd total: impossible

    const target = total / 2;
    const dp = new Array(target + 1).fill(false);
    dp[0] = true; // empty subset sums to 0

    for (const num of nums) {
        // RIGHT TO LEFT: 0/1 knapsack (each num used at most once)
        for (let j = target; j >= num; j--) {
            if (dp[j - num]) dp[j] = true;
            // Equivalent: dp[j] = dp[j] || dp[j - num];
        }
        if (dp[target]) return true; // early exit
    }
    return dp[target];
}

// TRACE on nums=[1,5,11,5], total=22, target=11:
// dp = [T,F,F,F,F,F,F,F,F,F,F,F]
// num=1: j=11..1. dp[1]=dp[0]=T.
//   dp = [T,T,F,F,F,F,F,F,F,F,F,F]
// num=5: j=11..5. dp[6]=dp[1]=T. dp[5]=dp[0]=T.
//   dp = [T,T,F,F,F,T,T,F,F,F,F,F]
// num=11: j=11. dp[11]=dp[0]=T -> RETURN TRUE
console.log(canPartition([1,5,11,5]));  // true  (subsets [1,5,5] and [11])
console.log(canPartition([1,2,3,5]));   // false (total=11, odd)
console.log(canPartition([1,2,5]));     // false (total=8, target=4: 1+2=3, 1+5=6, 2+5=7, no 4)

