// LIS O(n^2) DP
function lengthOfLIS_n2(nums) {
    const n = nums.length;
    const dp = new Array(n).fill(1); // each element is LIS of length 1

    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    return Math.max(...dp);
}
// [10,9,2,5,3,7,101,18]: dp=[1,1,1,2,2,3,4,4] -> max=4 (2,3,7,101 or 2,5,7,101)

// LIS O(n log n) patience sorting
function lengthOfLIS(nums) {
    const tails = []; // tails[k] = smallest tail of IS of length k+1

    for (const num of nums) {
        // Binary search: find leftmost position where tails[pos] >= num
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < num) lo = mid + 1;
            else hi = mid;
        }
        // lo is the position to update
        tails[lo] = num; // replace or extend
        // If lo === tails.length: num extends the longest IS seen so far
        // If lo < tails.length: num replaces tails[lo] (num is smaller, better future options)
    }
    return tails.length;
}

console.log(lengthOfLIS([10,9,2,5,3,7,101,18])); // 4
console.log(lengthOfLIS([0,1,0,3,2,3]));          // 4
console.log(lengthOfLIS([7,7,7,7,7]));             // 1 (strictly increasing)

