// EDIT DISTANCE (#72) — O(m*n) time, O(m*n) space
function minDistance_2D(word1, word2) {
    const m = word1.length, n = word2.length;
    // dp[i][j] = min edits to transform word1[0..i-1] to word2[0..j-1]
    const dp = Array.from({length: m+1}, (_, i) =>
        Array.from({length: n+1}, (_, j) => (i === 0 ? j : j === 0 ? i : 0))
    );
    // Base: dp[0][j] = j, dp[i][0] = i

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (word1[i-1] === word2[j-1]) {
                dp[i][j] = dp[i-1][j-1];               // match: free
            } else {
                dp[i][j] = 1 + Math.min(
                    dp[i-1][j-1],  // substitute
                    dp[i-1][j],    // delete from word1
                    dp[i][j-1]     // insert into word1
                );
            }
        }
    }
    return dp[m][n];
}

// SPACE OPTIMISED: O(n) space, two rows
function minDistance(word1, word2) {
    const m = word1.length, n = word2.length;
    let prev = Array.from({length: n+1}, (_, j) => j); // dp[0][j] = j
    let curr = new Array(n+1).fill(0);

    for (let i = 1; i <= m; i++) {
        curr[0] = i; // dp[i][0] = i
        for (let j = 1; j <= n; j++) {
            if (word1[i-1] === word2[j-1]) {
                curr[j] = prev[j-1];                    // match: diagonal
            } else {
                curr[j] = 1 + Math.min(prev[j-1], prev[j], curr[j-1]);
            }
        }
        [prev, curr] = [curr, prev];
    }
    return prev[n];
}

