function maxCoinsImpl(nums) {
  nums = [1, ...nums, 1];
  const n = nums.length;
  const dp = Array.from({length:n},()=>new Array(n).fill(0));
  for (let len = 2; len < n; len++) {
    for (let i = 0; i < n - len; i++) {
      const j = i + len;
      for (let k = i+1; k < j; k++) {
        const coins = nums[i] * nums[k] * nums[j];
        dp[i][j] = Math.max(dp[i][j], coins + dp[i][k] + dp[k][j]);
      }
    }
  }
  return dp[0][n-1];
}
